/** Deterministic Source204 constant. Bounded decode and exact bytes/SHA precede JSON parse. */
import assert from 'node:assert/strict';
import {createHash} from 'node:crypto';
import {brotliDecompressSync} from 'node:zlib';
const raw=brotliDecompressSync(Buffer.from('','base64'),{maxOutputLength:27030304});
assert.equal(raw.length,27030304,'Source204-exact-JSON-bytes');
assert.equal(createHash('sha256').update(raw).digest('hex'),'65004e2ccd59799b0bc55db9a3c4debdfec1ffe564856a9c06fd9b05600be771','Source204-exact-JSON-SHA');
export const PACKING204_SOURCE_CONTRACT=JSON.parse(raw.toString('utf8'));
